  if (firstOfType && openPoints <= 15) heat += 5;
  const cols = { [C.state]: { text: JSON.stringify(st) } };
  if (heat !== before) cols[C.heat] = String(heat);
  out.itemId = lead.it.id; out.colsJson = JSON.stringify(cols);
